-- StarUniv correction: standalone video tab + tools/external links


-- ============================================================================
-- 별도 영상 탭 (팬튜브 + 보자)
-- ============================================================================
create table if not exists public.video_channels (
  channel_url text primary key, channel_id text, title text, display_name text, thumb text, uploads text,
  source_order integer not null unique, active boolean not null default true, updated_at timestamptz not null default now()
);
create table if not exists public.videos (
  id text primary key, channel_url text, title text not null, published timestamptz, thumb text,
  views bigint not null default 0, short boolean not null default false, hidden boolean not null default false,
  updated_at timestamptz not null default now()
);
create index if not exists videos_published_idx on public.videos (published desc);
create index if not exists videos_channel_idx on public.videos (channel_url);
create table if not exists public.video_picks (
  id text primary key, kind text not null default 'youtube' check (kind in ('youtube','soop')), title text not null, note text,
  group_name text, group_en text, added_at date, author text, thumb text, short boolean not null default false,
  hidden boolean not null default false, source_order integer not null unique, updated_at timestamptz not null default now()
);
alter table public.video_channels enable row level security;
alter table public.videos enable row level security;
alter table public.video_picks enable row level security;

-- 관리자 CRUD
do $$ declare t text; begin
  foreach t in array array['video_channels','videos','video_picks'] loop
    execute format('drop policy if exists %I on public.%I', 'admins_all_' || t, t);
    execute format('create policy %I on public.%I for all to authenticated using (public.is_admin()) with check (public.is_admin())', 'admins_all_' || t, t);
  end loop;
end $$;
grant select,insert,update,delete on public.video_channels,public.videos,public.video_picks to authenticated;

-- 공개 영상 탭 읽기
revoke all on public.video_channels,public.videos,public.video_picks from anon;
grant select (channel_url,channel_id,title,display_name,thumb,uploads,source_order,active) on public.video_channels to anon;
grant select (id,channel_url,title,published,thumb,views,short,hidden) on public.videos to anon;
grant select (id,kind,title,note,group_name,group_en,added_at,author,thumb,short,hidden,source_order) on public.video_picks to anon;
drop policy if exists public_read_video_channels on public.video_channels;
create policy public_read_video_channels on public.video_channels for select to anon using (active=true);
drop policy if exists public_read_videos on public.videos;
create policy public_read_videos on public.videos for select to anon using (true);
drop policy if exists public_read_video_picks on public.video_picks;
create policy public_read_video_picks on public.video_picks for select to anon using (true);

-- ============================================================================
-- 도구 > 외부도구 (기존 어드민 관리 링크)
-- 멀티뷰어/엔트리/캄몬라이더 자체 기능은 Git에 남고, 여기에는 외부 링크만 저장한다.
-- ============================================================================
create table if not exists public.external_tools (
  id bigint generated by default as identity primary key,
  category text not null check (category in ('extTools','extSites')),
  name text not null,
  url text not null,
  favicon text,
  source_order integer not null unique,
  active boolean not null default true,
  updated_at timestamptz not null default now()
);
create index if not exists external_tools_category_order_idx on public.external_tools(category, source_order);
alter table public.external_tools enable row level security;

-- 현재 docs/data/tools.json 최초 시드. 이미 같은 URL이 있으면 건드리지 않는다.
select 'extTools','혹시','https://calm-hoxy.vercel.app/',null,1,true
where not exists (select 1 from public.external_tools where url='https://calm-hoxy.vercel.app/');
select 'extTools','암다리','https://prena.io/brain/',null,2,true
where not exists (select 1 from public.external_tools where url='https://prena.io/brain/');
select 'extTools','핀볼','https://lazygyu.github.io/roulette/',null,3,true
where not exists (select 1 from public.external_tools where url='https://lazygyu.github.io/roulette/');
select 'extTools','네이버 사다리','https://search.naver.com/search.naver?where=nexearch&query=%EC%82%AC%EB%8B%A4%EB%A6%AC%EA%B2%8C%EC%9E%84','https://naver.com/favicon.ico',4,true
where not exists (select 1 from public.external_tools where url='https://search.naver.com/search.naver?where=nexearch&query=%EC%82%AC%EB%8B%A4%EB%A6%AC%EA%B2%8C%EC%9E%84');
select 'extSites','EloBoard','https://eloboard.com/',null,5,true
where not exists (select 1 from public.external_tools where url='https://eloboard.com/');

-- 관리자 CRUD
drop policy if exists admins_all_external_tools on public.external_tools;
create policy admins_all_external_tools on public.external_tools for all to authenticated
using (public.is_admin()) with check (public.is_admin());
grant select,insert,update,delete on public.external_tools to authenticated;
grant usage,select on sequence public.external_tools_id_seq to authenticated;

-- 공개 사이트 읽기
revoke all on public.external_tools from anon;
grant select (id,category,name,url,favicon,source_order,active) on public.external_tools to anon;
drop policy if exists public_read_external_tools on public.external_tools;
create policy public_read_external_tools on public.external_tools for select to anon using (active=true);
